package workbench

// 与业务系统交换的事实类型；输入字段由调用方设置，动作写回输出字段。
declare RuleInput
    granaryId : String
    grainType : String
    storageState : String
    policyVersion : String
    batchId : String
    measuredAt : String
    expectedPoints : Integer
    actualPoints : Integer
    averageTemp : Double
    maxTemp : Double
    minTemp : Double
    coverageRate : Double
    unavailableRate : Double
    layerStats : String
    deltaTemp : Double
    historyComparable : Boolean
    baselineTime : String
    ruleCategory : String
    scopeType : String
    warnThreshold : Double
    criticalThreshold : Double
    recoverThreshold : Double
    minCoverage : Double
    policyEnabled : Boolean
    effectiveFrom : String
    effectiveTo : String
    hasActiveAlarm : Boolean
    activeLevel : String
    confirmState : String
    consecutiveBreaches : Integer
    assessmentCategory : String
    scopeKey : String
    assessmentState : String
    matchedBands : String
    maxCandidateLevel : String
    observedValue : Double
    threshold : Double
    reasons : String
    resultCode : String
    executionState : String
end

// COLLECT 命中策略输出的独立命中结果集合。
declare DecisionHit
    tableName : String
    ruleName : String
    rowIndex : Integer
    defaultRow : Boolean
    outputs : java.util.Map
end

rule "整仓均温判定决策表 第1行 [1]"
    salience 30000004
    no-loop true
when
    $input : RuleInput( coverageRate >= 0.8d, averageTemp >= 25d, hasActiveAlarm == false )
then
    java.util.Map $hitOutputs = new java.util.LinkedHashMap();
    $hitOutputs.put("assessmentState", "BREACH");
    $hitOutputs.put("assessmentCategory", "均温");
    $hitOutputs.put("maxCandidateLevel", "告警");
    $hitOutputs.put("threshold", "25");
    $hitOutputs.put("scopeKey", "均温-整仓");
    DecisionHit $hit = new DecisionHit();
    $hit.setTableName("整仓均温判定决策表");
    $hit.setRuleName("整仓均温判定决策表 第1行 [1]");
    $hit.setRowIndex(0);
    $hit.setDefaultRow(false);
    $hit.setOutputs($hitOutputs);
    insert($hit);
    modify($input) {
        setAssessmentState("BREACH"),
        setAssessmentCategory("均温"),
        setMaxCandidateLevel("告警"),
        setThreshold(25d),
        setScopeKey("均温-整仓")
    }
end

